namespace { std::string esc(const std::string& v){std::string o;for(char c:v){if(c=='\\')o+="\\\\";else if(c=='\"')o+="\\\"";else o+=c;}return o;} std::string fld(const std::string& b,const std::string& n,const std::string& f){auto p=b.find("\""+n+"\"");if(p==std::string::npos)return f;p=b.find(':',p);if(p==std::string::npos)return f;++p;while(p<b.size()&&(b[p]==' '||b[p]=='\t'))++p;auto e=b.find_first_of(",}",p);return b.substr(p,e==std::string::npos?b.size()-p:e-p);} uint64_t setting(const std::string& p,const std::string& k,uint64_t f){std::ifstream x(p+"/storage.env");std::string l;while(std::getline(x,l))if(l.rfind(k+"=",0)==0)try{return std::stoull(l.substr(k.size()+1));}catch(...){break;}return f;} }
Engine::Engine(std::string d):directory(std::move(d)),memtable(8),walFile(directory+"/wal.log"),tables(directory){std::filesystem::create_directories(directory);sequence=tables.maxGeneration();recover();}
Engine::~Engine(){stopSimulation();}
size_t Engine::memtableLimitBytes()const{return setting(directory,"MEMTABLE_SIZE_MB",1)*1024*1024;}
void Engine::recordLatency(std::array<size_t,9>& buckets,uint64_t& totalUs,uint64_t micros){std::lock_guard lock(mutex);totalUs+=micros;const uint64_t limits[]={50,100,250,500,1000,2500,5000,10000,static_cast<uint64_t>(-1)};size_t i=0;while(i<8&&micros>limits[i])++i;++buckets[i];}
uint64_t Engine::percentile(const std::array<size_t,9>& buckets,double q)const{size_t total=0;for(auto n:buckets)total+=n;if(!total)return 0;size_t target=static_cast<size_t>(std::ceil(total*q));target=std::max<size_t>(1,target);size_t seen=0;const uint64_t limits[]={50,100,250,500,1000,2500,5000,10000,10001};for(size_t i=0;i<9;++i){seen+=buckets[i];if(seen>=target)return limits[i];}return limits[8];}
void Engine::recover(){try{for(const auto& e:walFile.replay()){sequence=std::max(sequence,e.sequence);memtable.put(e.key,{e.value,e.operation=="DEL",e.sequence});}}catch(const std::runtime_error&){std::error_code x;std::filesystem::rename(directory+"/wal.log",directory+"/wal.log.legacy",x);if(x)throw;}}
void Engine::put(const std::string& k,const std::string& v){auto started=std::chrono::steady_clock::now();{std::lock_guard lock(mutex);walFile.append("PUT",k,v,++sequence);memtable.put(k,{v,false,sequence});logicalBytes+=k.size()+v.size();if(memtable.bytes()>=memtableLimitBytes())flush();++writeOperations;}recordLatency(writeLatencyBuckets,writeLatencyTotalUs,static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-started).count()));}
void Engine::del(const std::string& k){auto started=std::chrono::steady_clock::now();{std::lock_guard lock(mutex);walFile.append("DEL",k,"",++sequence);memtable.put(k,{"",true,sequence});logicalBytes+=k.size();if(memtable.bytes()>=memtableLimitBytes())flush();++writeOperations;}recordLatency(writeLatencyBuckets,writeLatencyTotalUs,static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-started).count()));}
bool Engine::get(const std::string& k,std::string& v){auto started=std::chrono::steady_clock::now();bool found=false;{std::lock_guard lock(mutex);++readOperations;Record r;if(memtable.get(k,r)){if(!r.tombstone){v=r.value;found=true;}}else{auto c=blockCache.find(k);if(c!=blockCache.end()){v=c->second.first;cacheOrder.splice(cacheOrder.begin(),cacheOrder,c->second.second);c->second.second=cacheOrder.begin();++cacheHits;found=true;}else if(tables.get(k,v,bloomRejects,diskReads)){cacheOrder.push_front(k);blockCache[k]={v,cacheOrder.begin()};if(blockCache.size()>128){auto old=cacheOrder.back();cacheOrder.pop_back();blockCache.erase(old);}found=true;}}if(!found)++readMisses;}recordLatency(readLatencyBuckets,readLatencyTotalUs,static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-started).count()));return found;}
void Engine::flush(){std::lock_guard lock(mutex);if(!memtable.size())return;auto r=memtable.snapshot();tables.write(r);for(const auto& [k,v]:r)internalBytes+=k.size()+v.value.size()+sizeof(Record);memtable.clear();walFile.truncate();++flushCount;}
size_t Engine::compact(){std::lock_guard lock(mutex);if(memtable.size())tables.write(memtable.snapshot(),"L0");memtable.clear();auto r=tables.compact();walFile.truncate();++compactionCount;return r;}
void Engine::crashRecover(){std::lock_guard lock(mutex);memtable.clear();recover();}
void Engine::clearAll(){stopSimulation();std::lock_guard lock(mutex);memtable.clear();walFile.truncate();tables.clear();sequence=0;logicalBytes=0;internalBytes=0;compactionBytes=0;readOperations=0;writeOperations=0;readMisses=0;cacheHits=0;diskReads=0;bloomRejects=0;flushCount=0;compactionCount=0;writeLatencyTotalUs=0;readLatencyTotalUs=0;writeLatencyBuckets.fill(0);readLatencyBuckets.fill(0);cacheOrder.clear();blockCache.clear();simulationWrites=0;simulationReads=0;startedAt=std::chrono::steady_clock::now();}
std::string Engine::status()const{std::lock_guard lock(mutex);size_t t=0;for(auto& x:memtable.snapshot())if(x.second.tombstone)++t;auto m=tables.metadata();double h=readOperations?double(readOperations-readMisses)/readOperations:0;std::ostringstream o;o<<"{\"memtableKeys\":"<<memtable.size()<<",\"memtableBytes\":"<<memtable.bytes()<<",\"tombstones\":"<<t<<",\"sstables\":"<<m.size()<<",\"walBytes\":"<<walFile.bytes()<<",\"walRecords\":"<<walFile.records()<<",\"readOps\":"<<readOperations<<",\"readMisses\":"<<readMisses<<",\"readHitRate\":"<<h<<",\"memtableType\":\"skip list\",\"skiplistLevels\":"<<memtable.levels()<<",\"flushCount\":"<<flushCount<<",\"compactionCount\":"<<compactionCount<<",\"cacheSize\":"<<blockCache.size()<<",\"simulationRunning\":"<<(simulationRunning?"true":"false")<<",\"simulationWrites\":"<<simulationWrites<<",\"simulationReads\":"<<simulationReads<<",\"simulationFrequencyMs\":"<<simulationFrequencyMs<<",\"simulationPayloadBytes\":"<<simulationPayloadBytes<<",\"memtablePreview\":[";size_t n=0;for(auto& [k,v]:memtable.snapshot(40)){if(n++)o<<',';o<<"{\"key\":\""<<esc(k)<<"\",\"state\":\""<<(v.tombstone?"TOMBSTONE":"VALUE")<<"\",\"bytes\":"<<k.size()+v.value.size()<<"}";}o<<"],\"sstableFiles\":[";for(size_t i=0;i<m.size();++i){if(i)o<<',';o<<"{\"name\":\""<<esc(m[i].name)<<"\",\"level\":\""<<m[i].level<<"\",\"records\":"<<m[i].records<<",\"bytes\":"<<m[i].bytes<<"}";}o<<"]}";return o.str();}
std::string Engine::metrics()const{std::lock_guard lock(mutex);size_t cm=readOperations>cacheHits?readOperations-cacheHits:0;size_t storage=walFile.bytes();for(const auto& table:tables.metadata())storage+=table.bytes;double elapsed=std::max(0.001,std::chrono::duration<double>(std::chrono::steady_clock::now()-startedAt).count());double writeThroughput=writeOperations/elapsed,readThroughput=readOperations/elapsed;double avgWrite=writeOperations?double(writeLatencyTotalUs)/writeOperations:0,avgRead=readOperations?double(readLatencyTotalUs)/readOperations:0;std::ostringstream o;o<<"{\"memtableType\":\"skip list\",\"skiplistLevels\":"<<memtable.levels()<<",\"memtableBytes\":"<<memtable.bytes()<<",\"sstableReadOps\":"<<diskReads<<",\"s3ReadCount\":"<<diskReads<<",\"bloomRejects\":"<<bloomRejects<<",\"cacheHits\":"<<cacheHits<<",\"cacheMisses\":"<<cm<<",\"cacheSize\":"<<blockCache.size()<<",\"flushCount\":"<<flushCount<<",\"compactionCount\":"<<compactionCount<<",\"storageUsageBytes\":"<<storage<<",\"writeOps\":"<<writeOperations<<",\"readOps\":"<<readOperations<<",\"writeThroughput\":"<<writeThroughput<<",\"readThroughput\":"<<readThroughput<<",\"avgWriteLatencyUs\":"<<avgWrite<<",\"avgReadLatencyUs\":"<<avgRead<<",\"writeP50Us\":"<<percentile(writeLatencyBuckets,.50)<<",\"writeP90Us\":"<<percentile(writeLatencyBuckets,.90)<<",\"writeP99Us\":"<<percentile(writeLatencyBuckets,.99)<<",\"readP50Us\":"<<percentile(readLatencyBuckets,.50)<<",\"readP90Us\":"<<percentile(readLatencyBuckets,.90)<<",\"readP99Us\":"<<percentile(readLatencyBuckets,.99)<<",\"pendingRequests\":"<<pendingRequests.load()<<",\"activeRequests\":"<<activeRequests.load()<<"}";return o.str();}
std::string Engine::wal()const{std::lock_guard lock(mutex);std::ostringstream o;o<<"[";auto e=walFile.replay();for(size_t i=0;i<e.size();++i){if(i)o<<',';o<<"{\"seq\":"<<e[i].sequence<<",\"operation\":\""<<e[i].operation<<"\",\"key\":\""<<esc(e[i].key)<<"\",\"valueBytes\":"<<e[i].value.size()<<"}";}o<<"]";return o.str();}
std::string Engine::sstables()const{std::lock_guard lock(mutex);std::ostringstream o;o<<"[";auto m=tables.metadata();for(size_t i=0;i<m.size();++i){if(i)o<<',';o<<"{\"name\":\""<<esc(m[i].name)<<"\",\"level\":\""<<m[i].level<<"\",\"records\":"<<m[i].records<<",\"bytes\":"<<m[i].bytes<<",\"indexBytes\":"<<m[i].indexEntries*16<<",\"bloom\":\"healthy\",\"minKey\":\""<<esc(m[i].minKey)<<"\",\"maxKey\":\""<<esc(m[i].maxKey)<<"\"}";}o<<"]";return o.str();}
std::string Engine::config()const{std::ostringstream o;o<<"{\"storage\":\"local files\",\"MEMTABLE_SIZE_MB\":"<<setting(directory,"MEMTABLE_SIZE_MB",1)<<",\"SSTABLE_SIZE_MB\":"<<setting(directory,"SSTABLE_SIZE_MB",4)<<",\"BLOCK_SIZE_KB\":"<<setting(directory,"BLOCK_SIZE_KB",4)<<",\"BLOCK_CACHE_SIZE_MB\":"<<setting(directory,"BLOCK_CACHE_SIZE_MB",256)<<",\"BLOOM_FPP\":\""<<fld(std::string(), "BLOOM_FPP", "0.01")<<"\",\"L0_COMPACTION_TRIGGER\":"<<setting(directory,"L0_COMPACTION_TRIGGER",4)<<",\"MAX_LEVELS\":"<<setting(directory,"MAX_LEVELS",3)<<",\"COMPACTION_POLICY\":\"leveled\"}";return o.str();}
void Engine::saveConfig(const std::string& b){std::ofstream f(directory+"/storage.env",std::ios::trunc);f<<"MEMTABLE_SIZE_MB="<<fld(b,"MEMTABLE_SIZE_MB","1")<<"\nSSTABLE_SIZE_MB="<<fld(b,"SSTABLE_SIZE_MB","4")<<"\nBLOCK_SIZE_KB="<<fld(b,"BLOCK_SIZE_KB","4")<<"\nBLOCK_CACHE_SIZE_MB="<<fld(b,"BLOCK_CACHE_SIZE_MB","256")<<"\nBLOOM_FPP="<<fld(b,"BLOOM_FPP","0.01")<<"\nL0_COMPACTION_TRIGGER="<<fld(b,"L0_COMPACTION_TRIGGER","4")<<"\nMAX_LEVELS="<<fld(b,"MAX_LEVELS","3")<<"\nCOMPACTION_POLICY="<<fld(b,"COMPACTION_POLICY","leveled")<<"\n";}
void Engine::startSimulation(int f,int p,int k){simulationFrequencyMs=std::clamp(f,20,10000);simulationPayloadBytes=std::clamp(p,16,1048576);simulationKeySpace=std::clamp(k,1,1000000);simulationStop=false;simulationRunning=true;if(!simulator.joinable())simulator=std::thread(&Engine::simulationLoop,this);}
void Engine::startSimulation(const std::string& configuration){auto number=[&](const std::string& key,int fallback){try{return std::stoi(fld(configuration,key,std::to_string(fallback)));}catch(...){return fallback;}};simulationPayloadBytes=std::clamp(number("payloadBytes",256),16,1048576);simulationKeySpace=std::clamp(number("keySpace",1000),1,1000000);simulationSpeedPercent=std::clamp(number("speed",100),10,1000);simulationReadPercent=std::clamp(number("readRatio",20),0,100);simulationDeletePercent=std::clamp(number("deleteRatio",10),0,100-simulationReadPercent.load());const char* names[]={"temperature","humidity","airQuality","noise","trafficCount","parkingOccupancy","vibration"};for(size_t i=0;i<7;++i){sensorEnabled[i]=number(std::string(names[i])+"Enabled",1)!=0;sensorRates[i]=std::clamp(number(std::string(names[i])+"Rate",1),1,1000);}simulationStop=false;simulationRunning=true;if(!simulator.joinable())simulator=std::thread(&Engine::simulationLoop,this);}
void Engine::stopSimulation(){simulationRunning=false;simulationStop=true;if(simulator.joinable())simulator.join();}
void Engine::resetSimulation(){stopSimulation();simulationWrites=0;simulationReads=0;}
void Engine::simulationLoop(){std::mt19937 g(std::random_device{}());size_t tick=0;while(!simulationStop){if(!simulationRunning){std::this_thread::sleep_for(std::chrono::milliseconds(40));continue;}int totalRate=0;for(size_t i=0;i<7;++i)if(sensorEnabled[i])totalRate+=sensorRates[i];if(!totalRate){std::this_thread::sleep_for(std::chrono::milliseconds(200));continue;}std::uniform_int_distribution<int> choose(1,totalRate),coin(0,99);int target=choose(g),sensor=0;for(;sensor<7;++sensor)if(sensorEnabled[sensor]&&(target-=sensorRates[sensor])<=0)break;std::string prefix[]={"temperature","humidity","air-quality","noise","traffic-count","parking","vibration"};std::string k=prefix[sensor]+"-sensor-"+std::to_string(std::uniform_int_distribution<int>(0,std::max(1,simulationKeySpace.load())-1)(g));int readCut=simulationReadPercent.load(),deleteCut=readCut+simulationDeletePercent.load(),action=coin(g);if(action<readCut){std::string v;get(k,v);++simulationReads;}else if(action<deleteCut){del(k);++simulationWrites;}else{std::string payload=prefix[sensor]+" value="+std::to_string(std::uniform_int_distribution<int>(0,9999)(g)/100.0);if(payload.size()<static_cast<size_t>(simulationPayloadBytes.load()))payload.append(static_cast<size_t>(simulationPayloadBytes.load())-payload.size(),'x');put(k,payload);++simulationWrites;}if(++tick%80==0)try{flush();}catch(...){ }if(tick%320==0)try{compact();}catch(...){ }int interval=std::max(1,1000*100/simulationSpeedPercent.load()/totalRate);std::this_thread::sleep_for(std::chrono::milliseconds(interval));}}
